/** One segment of a route: fixed text, or a named parameter. */
export type Segment =
  | { readonly kind: "literal"; readonly text: string }
  | { readonly kind: "param"; readonly name: string };

/** The MCP tool of an operation. Public tools need no scope. */
export interface Tool {
  readonly name: string;
  readonly scope: Scope | null;
  readonly prepareOnly: boolean;
}

/** One operation of the registry, as the application sees it. */
export interface Operation {
  readonly name: OpName;
  readonly method: Method;
  readonly path: string;
  readonly base: Base;
  readonly segments: readonly Segment[];
  readonly params: readonly string[];
  readonly body: boolean;
  readonly highRisk: boolean;
  readonly binding: boolean;
  readonly session: SessionNeed;
  readonly classification: Classification;
  readonly tool: Tool | null;
}

